// canonical.ts — the REFERENCE canonical-serialization + hash-chain function for the
// `gate_decisions[]` append-only log (work-item-schema v0.5.0, Track B of
// wi-analytics-lifecycle-review).
//
// THIS FILE IS THE PINNED DEFINITION. IU-B0's fixtures (valid.md + the four negatives)
// are generated by this code, and IU-B-guard's `vendor:check` guard imports THIS SAME
// FILE. The fixtures and the future CI check therefore share ONE serialization and
// cannot silently drift. Do not fork the hash/join/canonical rules into the guard —
// import them from here.
//
// PORTABILITY: `node:crypto` + `JSON` only. No Bun.* globals, no third-party deps
// (matches lib/transcript-usage.ts / analyzer/cursor.ts). B-guard can import this from
// the build pipeline without dragging in a YAML parser or any runtime — extracting the
// `gate_decisions` array from the carrier .md is the CALLER's job; this module operates
// purely on already-parsed JS objects.

import { createHash } from "node:crypto";
import { canonicalize } from "./canonical-json.ts";

// ─────────────────────────────────────────────────────────────────────────────
// The pinned primitives — H, ‖, and the genesis predecessor.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The hash function H. SHA-256, hex-encoded (64 lowercase hex chars).
 * Chosen for: stdlib (`node:crypto`), deterministic, collision-resistant, already the
 * renderer's hash of record (analyzer/cursor.ts `sha256Head`).
 */
export function H(input: string): string {
  return createHash("sha256").update(input, "utf8").digest("hex");
}

/**
 * The join byte ‖ — ASCII US (Unit Separator, 0x1F). A single control byte that cannot
 * occur in the hex `hash` field and is vanishingly unlikely (and structurally invalid)
 * inside a canonicalised JSON content blob, so the three concatenated parts
 * `canonical(content) ‖ seq ‖ hash_prev` are unambiguously delimited — no length-prefix
 * confusion, no separator-injection across the boundary.
 */
export const JOIN = "\x1f";

/**
 * The genesis predecessor hash_{-1}: a fixed empty predecessor (64 zeros), so the
 * seq=0 entry chains over a constant rather than a special-case. Matches the
 * work-item-schema invariant: "the genesis entry chains over a fixed empty predecessor."
 */
export const GENESIS_PREV = "0".repeat(64);

// ─────────────────────────────────────────────────────────────────────────────
// canonical(content) — deterministic serialization of one entry's content.
// ─────────────────────────────────────────────────────────────────────────────

/** One `gate_decisions[]` entry, per work-item-schema v0.5.0. */
export interface GateDecisionEntry {
  seq: number;
  hash: string;
  gate: string;
  decision: string;
  decision_provenance?: string;
  owner: string;
  timestamp: string;
  evidence_refs?: string[];
  confidence?: string;
  conditions?: string;
  override?: unknown;
  // The chain binds `seq` + `hash` explicitly (they are not part of `content`); any
  // other authored field IS content and is canonicalised below.
  [k: string]: unknown;
}

/**
 * The fields that are CHAIN METADATA, not content. `seq` and `hash` are bound into the
 * link separately (`canonical(content) ‖ seq ‖ hash_prev`), so they are excluded from
 * the canonical content blob — otherwise `seq` would be double-counted and the
 * (not-yet-computed) `hash` of the current entry would be self-referential.
 */
const CHAIN_META_KEYS = new Set(["seq", "hash"]);

// `canonicalize` (recursive object-key sort; arrays preserve order) is the shared, pinned
// key-ordering primitive — imported from lib/canonical-json.ts so this PINNED definition and
// analyzer/merge.ts's dedup key share ONE impl and cannot drift. `canonical()` below composes it
// with the chain-meta stripping; the byte output is unchanged from the former private copy.

/**
 * canonical(content_n): the deterministic serialization of entry n's CONTENT — every
 * authored field EXCEPT the chain metadata (`seq`, `hash`). Recursively key-sorted,
 * whitespace-free JSON. This is the exact string fed to H as `canonical(content_n)`.
 */
export function canonical(entry: GateDecisionEntry): string {
  const content: Record<string, unknown> = {};
  for (const key of Object.keys(entry)) {
    if (CHAIN_META_KEYS.has(key)) continue;
    content[key] = (entry as Record<string, unknown>)[key];
  }
  return JSON.stringify(canonicalize(content));
}

// ─────────────────────────────────────────────────────────────────────────────
// The per-entry chain link + whole-chain verification.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * hash_n = H( canonical(content_n) ‖ seq_n ‖ hash_{n-1} ).
 * `hashPrev` is GENESIS_PREV for the seq=0 entry.
 */
export function linkHash(entry: GateDecisionEntry, hashPrev: string): string {
  return H(canonical(entry) + JOIN + String(entry.seq) + JOIN + hashPrev);
}

/**
 * Recompute the full chain of expected hashes from the entries' content, ignoring the
 * `hash` field already embedded in each entry. Returns the expected `hash` per position.
 * (The test asserts these equal the embedded hashes — "recompute, don't trust".)
 */
export function recomputeChain(entries: GateDecisionEntry[]): string[] {
  const hashes: string[] = [];
  let prev = GENESIS_PREV;
  for (const entry of entries) {
    const h = linkHash(entry, prev);
    hashes.push(h);
    prev = h;
  }
  return hashes;
}

export type ChainFailure =
  | { ok: false; reason: "seq-noncontiguous"; at: number; expectedSeq: number; gotSeq: number }
  | { ok: false; reason: "hash-mismatch"; at: number; expected: string; got: string }
  | { ok: false; reason: "empty" };

export type ChainResult = { ok: true } | ChainFailure;

/**
 * verifyChain — the append-only chain check B-guard will run.
 *
 * Asserts the two structural properties a single submitted log can prove on its own:
 *   (1) contiguous `seq` from 0 (no gaps, no repeats), and
 *   (2) a valid chain: every entry's embedded `hash` equals its recomputed `linkHash`.
 *
 * Together these close EDIT (a changed content byte breaks that entry's hash and every
 * downstream hash), REORDER (each link binds `seq` + the prior hash, so a swap breaks the
 * chain at the swap), and TRUNCATE (dropping the tail leaves a shorter log whose own chain
 * still verifies — so truncation is NOT caught by this single-log check alone; it is caught
 * by the GROWTH-ONLY-vs-merge-base property, which compares two logs and is B-guard's job,
 * not a property of one isolated file). REPLAY (re-submitting a whole prior valid chain)
 * likewise verifies as a standalone chain and is caught only by the growth-only/prefix
 * check against the prior head.
 *
 * IU-B0's role: give B-guard machine-reproducible fixtures. valid.md proves (1)+(2) PASS.
 * tampered-edit / tampered-reorder prove (1)+(2) FAIL right here. tampered-truncate and
 * tampered-replay are valid standalone chains that PASS verifyChain but FAIL the
 * growth-only/prefix check against valid.md — so B0 also exports `isPrefixExtension`
 * below, and the self-check proves each negative fails on EXACTLY its own property.
 */
export function verifyChain(entries: GateDecisionEntry[]): ChainResult {
  if (entries.length === 0) return { ok: false, reason: "empty" };
  let prev = GENESIS_PREV;
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.seq !== i) {
      return { ok: false, reason: "seq-noncontiguous", at: i, expectedSeq: i, gotSeq: entry.seq };
    }
    const expected = linkHash(entry, prev);
    if (entry.hash !== expected) {
      return { ok: false, reason: "hash-mismatch", at: i, expected, got: entry.hash };
    }
    prev = expected;
  }
  return { ok: true };
}

/**
 * isPrefixExtension(oldChain, newChain): the GROWTH-ONLY property — `newChain` extends
 * `oldChain` as a prefix (same entries 0..k-1, then strictly more). This is the two-log
 * property that closes TRUNCATE (newChain shorter than oldChain ⇒ not an extension) and
 * REPLAY (resubmitting an old, shorter or equal chain ⇒ not a strict extension; a chain
 * forked at some point ⇒ the prefix diverges).
 *
 * B-guard runs this against the merge-base log. B0 uses it in the self-check to prove
 * tampered-truncate and tampered-replay each fail HERE (and pass verifyChain) — i.e. they
 * differ from valid.md only in the length/prefix dimension, not in content or order.
 */
export function isPrefixExtension(
  oldChain: GateDecisionEntry[],
  newChain: GateDecisionEntry[],
): boolean {
  if (newChain.length <= oldChain.length) return false; // truncate / replay-equal / replay-shorter
  const oldHashes = recomputeChain(oldChain);
  const newHashes = recomputeChain(newChain);
  for (let i = 0; i < oldChain.length; i++) {
    if (oldHashes[i] !== newHashes[i]) return false; // a fork before the old head
  }
  return true;
}
